/** Common-part groups relevant to a given truck (EV hides engine/fuel/exhaust). */
export function partsForTruck(model: FlatModel): PartGroup[] {
  const isEV = model.bodyType === "Electric";
  return PART_GROUPS.filter((g) => (!isEV || g.evSafe) && g.products.length > 0);
}
